SELECT COUNT(*)
FROM SURVEY_ANSWER
WHERE EVENT_SEQ = #{eventSeq}

SELECT COUNT(DISTINCT USER_SEQ)
FROM SURVEY_ANSWER
WHERE EVENT_SEQ = #{eventSeq}
AND QUESTION_SEQ = #{questionSeq}

SELECT COUNT(DISTINCT USER_SEQ)
FROM SURVEY_ANSWER
WHERE EVENT_SEQ = #{eventSeq}
AND QUESTION_SEQ = #{questionSeq}
AND ITEM_SEQ = #{itemSeq}

SELECT COUNT(DISTINCT USER_SEQ)
FROM SURVEY_ANSWER
WHERE EVENT_SEQ = #{eventSeq}
AND QUESTION_SEQ = #{questionSeq}
AND QUESTION_TYPE = 'MCM'
AND (
    ANSWER = #{itemValue}
    OR ANSWER LIKE CONCAT(#{itemValue}, ',%')
    OR ANSWER LIKE CONCAT('%,', #{itemValue}, ',%')
    OR ANSWER LIKE CONCAT('%,', #{itemValue})
)

